func (m *metricCiscoOpticsTxPower) recordDataPoint(start pcommon.Timestamp, ts pcommon.Timestamp, val float64, networkInterfaceNameAttributeValue string, ciscoOpticsLaneAttributeValue string, ciscoOpticsSensorAttributeValue string, ciscoOpticsProfileAttributeValue string, ciscoOpticsExperimentalAttributeValue bool) {
	if !m.config.Enabled {
		return
	}

	dp := pmetric.NewNumberDataPoint()
	dp.SetStartTimestamp(start)
	dp.SetTimestamp(ts)
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsTxPowerMetricAttributeKeyNetworkInterfaceName) {
		dp.Attributes().PutStr("network.interface.name", networkInterfaceNameAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsTxPowerMetricAttributeKeyCiscoOpticsLane) {
		dp.Attributes().PutStr("cisco.optics.lane", ciscoOpticsLaneAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsTxPowerMetricAttributeKeyCiscoOpticsSensor) {
		dp.Attributes().PutStr("cisco.optics.sensor", ciscoOpticsSensorAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsTxPowerMetricAttributeKeyCiscoOpticsProfile) {
		dp.Attributes().PutStr("cisco.optics.profile", ciscoOpticsProfileAttributeValue)
	}
	if slices.Contains(m.config.EnabledAttributes, CiscoOpticsTxPowerMetricAttributeKeyCiscoOpticsExperimental) {
		dp.Attributes().PutBool("cisco.optics.experimental", ciscoOpticsExperimentalAttributeValue)
	}

	var s string
	dps := m.data.Gauge().DataPoints()
	for i := 0; i < dps.Len(); i++ {
		dpi := dps.At(i)
		if dp.Attributes().Equal(dpi.Attributes()) && dp.StartTimestamp() == dpi.StartTimestamp() && dp.Timestamp() == dpi.Timestamp() {
			switch s = m.config.AggregationStrategy; s {
			case AggregationStrategySum, AggregationStrategyAvg:
				dpi.SetDoubleValue(dpi.DoubleValue() + val)
				m.aggDataPoints[i] += 1
				return
			case AggregationStrategyMin:
				if dpi.DoubleValue() > val {
					dpi.SetDoubleValue(val)
				}
				return
			case AggregationStrategyMax:
				if dpi.DoubleValue() < val {
					dpi.SetDoubleValue(val)
				}
				return
			}
		}
	}

	dp.SetDoubleValue(val)
	m.aggDataPoints = append(m.aggDataPoints, 1)
	dp.MoveTo(dps.AppendEmpty())
}

